import 'dart:convert';
import 'dart:io';

import 'package:package_config/package_config.dart';
import 'package:path/path.dart' as p;
import 'package:skills_sync/src/copy_plan.dart';
import 'package:skills_sync/src/ship_map.dart';
import 'package:skills_sync/src/skill_dir.dart';
import 'package:skills_sync/src/skills_sync_exception.dart';

const _skillFile = 'SKILL.md';
const _referencesDir = 'references';
const _generatedFile = 'GENERATED';
const _generatedHeader =
    '# Generated by tool/skills_sync. Do not edit; run melos run skills:sync.';

/// Finder metadata, never part of a skill.
const _ignoredFile = '.DS_Store';

/// Returns the root directory of each of [names] from the package config in
/// [repoRoot].
///
/// Throws [SkillsSyncException] when the package config is missing or lacks a
/// name.
Future<Map<String, String>> resolvePackageRoots(
  String repoRoot,
  Iterable<String> names,
) async {
  final configFile = File(
    p.join(repoRoot, '.dart_tool', 'package_config.json'),
  );
  if (!configFile.existsSync()) {
    throw SkillsSyncException(
      '${configFile.path} is missing; run `dart pub get` (or '
      '`melos bootstrap`) at the repository root',
    );
  }
  final config = await loadPackageConfig(configFile);
  return {
    for (final name in names)
      name: p.normalize(
        (config[name] ??
                (throw SkillsSyncException(
                  '$name is not in the package config',
                )))
            .root
            .toFilePath(),
      ),
  };
}

/// Returns the `skills/` directory of every key of [ships], each a package the
/// tool writes to.
///
/// Throws [SkillsSyncException] when a key's root is outside [repoRoot].
/// [ships] defaults to [shipMap].
Future<List<String>> targetSkillsDirectories(
  String repoRoot, {
  Map<String, List<String>> ships = shipMap,
}) async {
  final roots = await _resolveRoots(repoRoot, ships);
  return [for (final package in ships.keys) p.join(roots[package]!, 'skills')];
}

/// Resolves the root of every key and value of [ships].
///
/// Keys are written to, so each must sit inside [repoRoot]; values may live
/// anywhere, such as the pub cache, but must exist. Throws
/// [SkillsSyncException] otherwise.
Future<Map<String, String>> _resolveRoots(
  String repoRoot,
  Map<String, List<String>> ships,
) async {
  final roots = await resolvePackageRoots(repoRoot, {
    ...ships.keys,
    for (final shipped in ships.values) ...shipped,
  });
  final repo = p.normalize(p.absolute(repoRoot));
  for (final entry in roots.entries) {
    if (ships.containsKey(entry.key)) {
      if (!p.isWithin(repo, entry.value)) {
        throw SkillsSyncException(
          '${entry.key} resolves to ${entry.value}, outside the repository '
          '$repo; the tool writes to every ship-map key, so a key must be a '
          'package of this repository',
        );
      }
    } else if (!Directory(entry.value).existsSync()) {
      throw SkillsSyncException(
        '${entry.key} resolves to ${entry.value}, which does not exist; run '
        '`dart pub get` (or `melos bootstrap`) at the repository root',
      );
    }
  }
  return roots;
}

/// Rewrites every package's generated skill copies and `GENERATED` file.
///
/// Writes only to the packages that are keys of [ships]; a package named only
/// as a value is a read-only source. Validates every source before it deletes
/// or writes anything; throws [SkillsSyncException] for a symlink under a
/// key's `skills/` or inside a copied source skill, or a source `SKILL.md`
/// without a name. Lists old and new copies in `GENERATED` before the first
/// delete, so an interrupted run is recoverable by running again. Returns the
/// copy directories written. [ships] defaults to [shipMap].
Future<List<String>> runSync(
  String repoRoot, {
  Map<String, List<String>> ships = shipMap,
}) async {
  final plan = await _Plan.load(repoRoot, ships);
  for (final package in ships.keys) {
    _requireNoSymlinks(plan.skillsDir(package));
  }
  plan.readOnlySourceDirs.forEach(_requireNoSymlinks);
  final staleDirs = [
    for (final package in ships.keys) ...plan.generatedDirs(package),
  ];
  final skillMds = {
    for (final copy in plan.copies) copy: _renamedSkillMd(copy),
  };
  for (final package in ships.keys) {
    _writeGenerated(plan, package, {
      ...readGenerated(plan.skillsDir(package)),
      ...plan.copyNames(package),
    });
  }
  staleDirs.forEach(_deleteDir);
  final written = <String>[];
  for (final copy in plan.copies) {
    final targetDir = plan.targetDir(copy);
    _writeCopy(copy, targetDir, skillMds[copy]!);
    written.add(targetDir);
  }
  for (final package in ships.keys) {
    _writeGenerated(plan, package, plan.copyNames(package));
  }
  return written;
}

/// Returns every way the repository's skills differ from what [runSync] writes.
///
/// An empty list means clean. Prefix, name, symlink, and `GENERATED` checks
/// cover the keys of [ships]; a source named only as a value is read, never
/// checked for those. [ships] defaults to [shipMap].
Future<List<String>> runCheck(
  String repoRoot, {
  Map<String, List<String>> ships = shipMap,
}) async {
  final plan = await _Plan.load(repoRoot, ships);
  return [
    for (final copy in plan.copies) ..._copyProblems(plan, copy),
    for (final package in ships.keys) ..._symlinkProblems(plan, package),
    for (final dir in plan.readOnlySourceDirs) ..._symlinkProblemsIn(dir),
    for (final package in ships.keys) ..._generatedProblems(plan, package),
    for (final package in ships.keys) ..._skillDirProblems(plan, package),
    ..._crossNameProblems(plan),
  ];
}

class _Plan {
  const new({
    required this.targets,
    required this.roots,
    required this.ownSkills,
    required this.copies,
  });

  static Future<_Plan> load(
    String repoRoot,
    Map<String, List<String>> ships,
  ) async {
    final roots = await _resolveRoots(repoRoot, ships);
    final ownSkills = {
      for (final entry in roots.entries)
        entry.key: _ownSkills(p.join(entry.value, 'skills')),
    };
    return _Plan(
      targets: ships.keys.toSet(),
      roots: roots,
      ownSkills: ownSkills,
      copies: planCopies(
        shipMap: ships,
        ownSkills: ownSkills,
        packageRoots: roots,
      ),
    );
  }

  /// The packages the tool writes to: the keys of the ship map.
  final Set<String> targets;
  final Map<String, String> roots;
  final Map<String, List<String>> ownSkills;
  final List<SkillCopy> copies;

  /// The skill directories copied from a package that is not a target; nothing
  /// else of such a package is read.
  Set<String> get readOnlySourceDirs => {
    for (final copy in copies)
      if (!targets.contains(copy.sourcePackage)) copy.sourceDir,
  };

  String skillsDir(String package) => p.join(roots[package]!, 'skills');

  String targetDir(SkillCopy copy) =>
      p.join(skillsDir(copy.targetPackage), copy.targetName);

  List<String> copyNames(String package) => [
    for (final copy in copies)
      if (copy.targetPackage == package) copy.targetName,
  ]..sort();

  /// The directories `GENERATED` lists, each checked to sit directly in
  /// `skills/` before anything deletes it.
  List<String> generatedDirs(String package) {
    final skills = skillsDir(package);
    return [
      for (final name in readGenerated(skills))
        if (p.equals(p.dirname(p.normalize(p.join(skills, name))), skills))
          p.join(skills, name)
        else
          throw SkillsSyncException(
            '$skills/$_generatedFile lists $name outside skills',
          ),
    ];
  }
}

/// Directories under [skillsDir] holding a `SKILL.md` that `GENERATED` does
/// not list.
List<String> _ownSkills(String skillsDir) {
  final generated = readGenerated(skillsDir).toSet();
  return [
    for (final name in _subdirectories(skillsDir))
      if (!generated.contains(name) &&
          File(p.join(skillsDir, name, _skillFile)).existsSync())
        name,
  ];
}

List<String> _subdirectories(String dir) => !Directory(dir).existsSync()
    ? const []
    : ([
        for (final entity in Directory(dir).listSync(followLinks: false))
          if (entity is Directory) p.basename(entity.path),
      ]..sort());

/// Relative paths of every file under [dir], sorted.
List<String> _files(String dir) => [
  for (final entity in Directory(
    dir,
  ).listSync(recursive: true, followLinks: false))
    if (entity is File && p.basename(entity.path) != _ignoredFile)
      p.relative(entity.path, from: dir),
]..sort();

/// Paths of every symlink under [dir]; skills ship as plain files.
List<String> _symlinks(String dir) {
  if (FileSystemEntity.isLinkSync(dir)) return [dir];
  if (!Directory(dir).existsSync()) return const [];
  return [
    for (final entity in Directory(
      dir,
    ).listSync(recursive: true, followLinks: false))
      if (entity is Link) entity.path,
  ];
}

void _requireNoSymlinks(String skillsDir) {
  final links = _symlinks(skillsDir);
  if (links.isNotEmpty) {
    throw SkillsSyncException('symlinks under skills/: ${links.join(', ')}');
  }
}

/// Returns the source `SKILL.md` of [copy] renamed to the copy's name.
String _renamedSkillMd(SkillCopy copy) {
  final source = File(p.join(copy.sourceDir, _skillFile));
  try {
    return rewriteName(source.readAsStringSync(), copy.targetName);
  } on FormatException catch (error) {
    throw SkillsSyncException('${source.path}: ${error.message}');
  }
}

void _deleteDir(String dir) {
  if (Directory(dir).existsSync()) Directory(dir).deleteSync(recursive: true);
}

void _writeCopy(SkillCopy copy, String targetDir, String skillMd) {
  for (final relative in _files(copy.sourceDir)) {
    final source = File(p.join(copy.sourceDir, relative));
    final target = File(p.join(targetDir, relative))
      ..parent.createSync(recursive: true);
    if (relative == _skillFile) {
      target.writeAsStringSync(skillMd);
    } else {
      source.copySync(target.path);
    }
  }
}

void _writeGenerated(_Plan plan, String package, Iterable<String> names) {
  final file = File(p.join(plan.skillsDir(package), _generatedFile));
  final sorted = names.toSet().toList()..sort();
  if (sorted.isEmpty) {
    if (file.existsSync()) file.deleteSync();
    return;
  }
  file
    ..parent.createSync(recursive: true)
    ..writeAsStringSync('$_generatedHeader\n${sorted.join('\n')}\n');
}

List<String> _copyProblems(_Plan plan, SkillCopy copy) {
  final targetDir = plan.targetDir(copy);
  if (!Directory(targetDir).existsSync()) {
    return ['$targetDir: missing copy of ${copy.sourceDir}'];
  }
  final sourceFiles = _files(copy.sourceDir);
  return [
    for (final relative in sourceFiles)
      ?_fileProblem(copy, targetDir, relative),
    for (final relative in _files(targetDir))
      if (!sourceFiles.contains(relative))
        '${p.join(targetDir, relative)}: not in ${copy.sourceDir}',
  ];
}

String? _fileProblem(SkillCopy copy, String targetDir, String relative) {
  final source = File(p.join(copy.sourceDir, relative));
  final target = File(p.join(targetDir, relative));
  if (!target.existsSync()) return '${target.path}: missing';
  final bool same;
  if (relative == _skillFile) {
    try {
      same =
          rewriteName(source.readAsStringSync(), copy.targetName) ==
          target.readAsStringSync();
    } on FormatException catch (error) {
      return '${source.path}: ${error.message}';
    }
  } else {
    same = _sameBytes(source.readAsBytesSync(), target.readAsBytesSync());
  }
  return same ? null : '${target.path}: differs from ${source.path}';
}

bool _sameBytes(List<int> a, List<int> b) {
  if (a.length != b.length) return false;
  for (var i = 0; i < a.length; i++) {
    if (a[i] != b[i]) return false;
  }
  return true;
}

List<String> _generatedProblems(_Plan plan, String package) {
  final skills = plan.skillsDir(package);
  final planned = plan.copyNames(package);
  return [
    for (final name in readGenerated(skills))
      if (!planned.contains(name))
        '${p.join(skills, name)}: listed in GENERATED without a plan entry',
  ];
}

List<String> _symlinkProblems(_Plan plan, String package) =>
    _symlinkProblemsIn(plan.skillsDir(package));

List<String> _symlinkProblemsIn(String dir) => [
  for (final link in _symlinks(dir))
    '$link: symlinks are not allowed under skills/',
];

List<String> _skillDirProblems(_Plan plan, String package) {
  final skills = plan.skillsDir(package);
  final prefixes = {'$package-', '${package.replaceAll('_', '-')}-'};
  return [
    for (final name in _subdirectories(skills)) ...[
      if (!prefixes.any(name.startsWith))
        '${p.join(skills, name)}: lacks the prefix ${prefixes.join(' or ')}',
      ?_nameProblem(p.join(skills, name, _skillFile), name),
    ],
  ];
}

String? _nameProblem(String skillFile, String directoryName) {
  final file = File(skillFile);
  if (!file.existsSync()) return null;
  final name = readSkillName(file.readAsStringSync());
  if (name == directoryName) return null;
  return name == null
      ? '$skillFile: frontmatter has no name'
      : '$skillFile: name is $name but the directory is $directoryName';
}

List<String> _crossNameProblems(_Plan plan) {
  final planned = {
    for (final skills in plan.ownSkills.values) ...skills,
    for (final copy in plan.copies) copy.targetName,
  };
  final patterns = {
    for (final name in planned)
      name: RegExp('(?<![\\w-])${RegExp.escape(name)}(?![\\w-])'),
  };
  return [
    for (final entry in plan.ownSkills.entries)
      for (final skill in entry.value)
        for (final file in _skillTextFiles(
          p.join(plan.skillsDir(entry.key), skill),
        ))
          ..._mentions(file, skill, patterns),
  ];
}

/// Problems for each planned name other than [skill] that [file] mentions.
///
/// Reads [file] once and skips it when it is not UTF-8 text.
List<String> _mentions(
  String file,
  String skill,
  Map<String, RegExp> patterns,
) {
  final String text;
  try {
    text = utf8.decode(File(file).readAsBytesSync());
  } on FormatException {
    return const [];
  }
  return [
    for (final other in patterns.entries)
      if (other.key != skill && other.value.hasMatch(text))
        '$file: mentions ${other.key}',
  ];
}

/// Absolute paths of `SKILL.md` and every file under `references/`.
List<String> _skillTextFiles(String skillDir) => [
  for (final relative in _files(skillDir))
    if (relative == _skillFile || p.isWithin(_referencesDir, relative))
      p.join(skillDir, relative),
];
